files.dispatch/pricing.py:
def fee(parcels):
    """Calculate the charge in credits for a submitted parcel count.

    The service includes this amount in its queued record. Address
    handling and label creation belong to the caller, not pricing.
    """
    return parcels * (4 if parcels >= 4 else 5)
